/**
 * Wire routing integrity (rt2): the golden canonical routes. Each case is a seeded random bench
 * (routingBench.ts) routed canonically, then one part moved and routed again. The fixture
 * `fixtures/rt2-canonical-routes.json` was generated by the router of fae6a3c (BEFORE any rt2
 * performance change), so a later optimization must reproduce every route bit for bit.
 */
import { createHash } from 'node:crypto';
import { emptySelection, moveSelection, wireRoute, type ProjectDocument } from '@tbi-lab/domain';
import { randomBench, rng } from './routingBench.js';

export interface GoldenCase {
  wires: number;
  seed: number;
  dense: boolean;
  board: boolean;
}

export const GOLDEN_CASES: GoldenCase[] = [
  ...[5, 10, 20, 40].flatMap((wires) =>
    [1, 2].flatMap((seed) => [
      { wires, seed, dense: false, board: false },
      { wires, seed, dense: true, board: false },
      { wires, seed, dense: true, board: true },
    ]),
  ),
  { wires: 80, seed: 1, dense: true, board: true },
];

export const caseKey = (c: GoldenCase) =>
  `${c.wires}-${c.seed}${c.dense ? '-dense' : ''}${c.board ? '-board' : ''}`;

export const routesHash = (doc: ProjectDocument) =>
  createHash('sha256')
    .update(JSON.stringify(doc.layout.wires.map((w) => [w.id, w.vertices, wireRoute(doc, w)])))
    .digest('hex');

/** The case's two documents: routed as opened, and after moving one part. */
export function goldenDocs(
  c: GoldenCase,
  route: (doc: ProjectDocument) => ProjectDocument,
): { open: ProjectDocument; moved: ProjectDocument } {
  const b = randomBench(c.wires, c.seed, { dense: c.dense, board: c.board });
  const open = route(b.doc);
  const R = rng(c.seed * 7919);
  for (let k = 0; k < 10; k++) {
    const part = b.parts[Math.floor(R() * b.parts.length)]!;
    const d = { x: 20 * Math.round(R() * 6 - 3), y: 20 * Math.round(R() * 6 - 3) };
    const m = moveSelection(open, { ...emptySelection(), components: [part] }, d);
    if (m.ok) return { open, moved: route(m.doc) };
  }
  throw new Error(`no legal move for ${caseKey(c)}`);
}
